  1	/**
  2	 * ABI contract between the orchestrator and any executor.
  3	 *
  4	 * The orchestrator serialises ExecutorInput into env vars before spawning
  5	 * the executor process. The executor writes an ExecutorResult to the path
  6	 * at resultPath. The orchestrator reads and validates that file on exit.
  7	 */
  8	
  9	// ── Handle / completion types (Wave 1 — ports-and-adapters foundation) ───────
 10	
 11	/** Opaque identifier for a single in-flight executor run. */
 12	export type ExecutorHandle = string;
 13	
 14	/** Discriminates claim work from review-fix work in the reap loop. */
 15	export type HandleKind = "impl" | "review-fix" | "review" | "rebase";
 16	
 17	/** Sub-discriminator for review-fix handles. */
 18	export type HandleSubkind = "rebase" | "respond";
 19	
 20	/**
 21	 * Metadata registered with the broker at submit time.
 22	 * Carried on every completion so any orchestrator can dispatch without
 23	 * needing prior knowledge of the submit — opportunistic dispatch.
 24	 */
 25	export interface HandleMetadata {
 26	  kind: HandleKind;
 27	  subkind?: HandleSubkind;
 28	  task_id: string;
 29	  feature_id: string;
 30	  tenant_id?: string;
 31	  started_at: string; // ISO 8601
 32	}
 33	
 34	/**
 35	 * One item returned by CompletionBrokerPort.listCompleted (peek-and-lock).
 36	 * locked_until is present when the broker has marked the item locked.
 37	 */
 38	export interface ExecutorCompletion {
 39	  handle: ExecutorHandle;
 40	  result: ExecutorResult;
 41	  metadata: HandleMetadata;
 42	  locked_until?: number; // unix ms timestamp
 43	}
 44	
 45	/**
 46	 * Extended input for ExecutorPort.submit.
 47	 * Adds the callback URL and per-handle nonce that the runner wrapper uses
 48	 * to POST its result back to the completion broker.
 49	 */
 50	export interface ExecutorPortInput extends ExecutorInput {
 51	  /** The URL the runner wrapper will POST { handle, nonce, result } to. */
 52	  callbackUrl: string;
 53	  /** Single-use token; validated by the broker on POST; invalidated on ack. */
 54	  nonce: string;
 55	  /**
 56	   * Override the handle kind registered with the broker. When absent the
 57	   * adapter falls back to its constructor-level handleKind (defaulting to "impl").
 58	   */
 59	  kind?: HandleKind;
 60	}
 61	
 62	/** HTTP POST body the runner wrapper sends to the broker on completion. */
 63	export interface RunnerCallbackPayload {
 64	  handle: ExecutorHandle;
 65	  nonce: string;
 66	  result: ExecutorResult;
 67	}
 68	
 69	// ── Original ABI types (kept for backward compatibility) ─────────────────────
 70	
 71	export interface ExecutorInput {
 72	  taskId: string;
 73	  featureId: string;
 74	  workspaceId: string;
 75	  /** Executor invocation UUID. Passed as `HANDLE` env var; formalises existing docker usage. */
 76	  handle: string;
 77	  /** Git URL of the implementation repo (SSH or HTTPS). */
 78	  taskRepoUrl: string;
 79	  /** Feature branch the executor must check out and push to. */
 80	  taskRepoBranch: string;
 81	  /**
 82	   * Branch that implementation PRs must target. Set by the orchestrator to the
 83	   * feature branch (e.g. `feature/{featureId}`) so task PRs collect there before
 84	   * the Handoff Trigger merges the feature branch into the repo's base branch.
 85	   * Executors read this as `TASK_BASE_BRANCH` and pass it as the `base` field
 86	   * when calling `pr-create`.
 87	   */
 88	  taskBaseBranch: string;
 89	  /**
 90	   * The impl repo's root base branch from workspace.yaml (e.g. `main`).
 91	   * Used by the executor to create `feature/{featureId}` on the impl repo remote
 92	   * when it does not yet exist. Distinct from `taskBaseBranch`, which is the PR
 93	   * target (the feature branch itself) and must not be used as a push source.
 94	   * Executors read this as `TASK_REPO_BASE_BRANCH`.
 95	   */
 96	  taskRepoBaseBranch?: string;
 97	  /**
 98	   * Per-handle base directory. The executor derives:
 99	   *   - `${executorWorkdir}/impl` — implementation repo (replaces `taskRepoPath`)
100	   *   - `${executorWorkdir}/mgmt` — management repo clone (derives `WORKSPACE_ROOT`)
101	   */
102	  executorWorkdir: string;
103	  /** Git URL of the management (workspace) repo — cloned read-only by the executor. */
104	  mgmtRepoUrl: string;
105	  /** Path the executor must write result.json to. */
106	  resultPath: string;
107	  /** Optional token budget; absent for non-LLM executors. */
108	  budgetTokens?: number;
109	  /** Model ID to use for the LLM; resolved from workspace model_policy. */
110	  implementationModel?: string;
111	  sshPrivateKey: string;
112	  githubToken: string;
113	}
114	
115	export type TerminalStatus = "in_review" | "blocked" | "failed";
116	
117	export interface ExecutorResult {
118	  terminal_status: TerminalStatus;
119	  token_usage?: { input: number; output: number; model?: string };
120	  /** Required when terminal_status === "blocked". */
121	  blocked_reason?: string;
122	  /** Required when terminal_status === "blocked". */
123	  blocked_suggestion?: string;
124	  /**
125	   * URL of the implementation-repo pull request opened by the executor.
126	   * Populated whenever the executor opened a PR — independent of terminal_status.
127	   * A blocked task with a draft PR still reports pr_url so the failed attempt is
128	   * documented. Absent when no commits were pushed (no PR to open).
129	   */
130	  pr_url?: string;
131	  /**
132	   * Path to a handover.md file written by the executor or the post-hoc recovery
133	   * routine (Layer 1). Optional — present only when a handover exists.
134	   * The orchestrator reads this on re-claim and prepends its contents to the next
135	   * agent's briefing under a "## Continuing previous run" heading (Layer 3).
136	   */
137	  cost_usd?: number;
138	  handover_path?: string;
139	}
140	
141	/** Terminal status values produced by the reviewer executor (kind=review). */
142	export type ReviewerTerminalStatus = "passed" | "change_requested" | "escalate";
143	
144	/**
145	 * Result written by the reviewer executor to result.json.
146	 * Routed to dispatchReviewResult in the reap loop — separate from ExecutorResult.
147	 */
148	export interface ReviewerResult {
149	  terminal_status: ReviewerTerminalStatus;
150	  verdict: ReviewerTerminalStatus;
151	  confidence: number;
152	  notes: string;
153	  review_url?: string;
154	  /** Set to true when the review POST was skipped due to HTTP 422 (self-review restriction). */
155	  self_review_skipped?: boolean;
156	}
157	
158	/**
159	 * The orchestrator-side seam every executor must satisfy.
160	 * The default implementation is SubProcessAdapter; tests use FakeAdapter.
161	 */
162	export interface ExecutorAdapter {
163	  run(input: ExecutorInput): Promise<ExecutorResult>;
164	}

