 /**

  1	/**
  2	 * Hermes executor entrypoint — ABI-conformant.
  3	 *
  4	 * Reads ExecutorInput from environment variables, runs phases 1–5, then
  5	 * post-execution (Phase 6) commits, pushes, opens the impl PR, and writes result.json.
  6	 *
  7	 * Formal ABI env vars (from ExecutorInput):
  8	 *   TASK_ID, FEATURE_ID, WORKSPACE_ID, HANDLE
  9	 *   TASK_REPO_URL, TASK_REPO_BRANCH, TASK_BASE_BRANCH, TASK_REPO_BASE_BRANCH
 10	 *   EXECUTOR_WORKDIR, MGMT_REPO_URL
 11	 *   RESULT_PATH
 12	 *   SSH_PRIVATE_KEY, GITHUB_TOKEN
 13	 *
 14	 * Hermes-specific env vars (injected via SubProcessAdapterOpts.extraEnv):
 15	 *   HERMES_INFERENCE_MODEL    — model ID (e.g. deepseek-v4-flash)
 16	 *   HERMES_INFERENCE_PROVIDER — provider (e.g. deepseek)
 17	 *   HERMES_MAX_TURNS          — max tool iterations (default 150)
 18	 *   RAG_MCP_URL               — optional RAG MCP server URL
 19	 *   RAG_MCP_TOKEN             — optional RAG MCP auth token
 20	 *   TASK_BRANCH               — mgmt repo branch to check out (default: feature/${featureId}-${taskId})
 21	 *
 22	 * Startup phases:
 23	 *   Phase 1: clone management repo (read-only)
 24	 *   Phase 2: clone implementation repo onto TASK_REPO_BRANCH
 25	 *   Phase 3: write HERMES_HOME/config.yaml (model + optional MCP stanza)
 26	 *   Phase 4: build briefing from mgmt clone
 27	 *   Phase 5: spawn hermes chat in try/finally (recovery fires in finally)
 28	 *   Phase 6: wrapper commits + pushes + opens impl PR + writes result.json [T4]
 29	 */
 30	
 31	import { spawn, execSync, spawnSync } from "node:child_process";
 32	import {
 33	  mkdirSync,
 34	  writeFileSync,
 35	  existsSync,
 36	  rmSync,
 37	  copyFileSync,
 38	  readdirSync,
 39	  readFileSync,
 40	  appendFileSync,
 41	} from "node:fs";
 42	import { join, dirname } from "node:path";
 43	import { stringify as yamlStringify } from "yaml";
 44	import type { ExecutorResult } from "@workflow/runtime-abi";
 45	import { runRecovery, parseGitHubCoords, type SpawnResult } from "./recovery.js";
 46	import { buildBriefing } from "./briefing.js";
 47	import { resolveSSHKey } from "./resolve-ssh-key.js";
 48	import { buildGitEnv } from "./git-env.js";
 49	import { ensureImplFeatureBranch } from "./impl-feature-branch.js";
 50	import { flushLog } from "./flush-log.js";
 51	
 52	// ── Helpers ────────────────────────────────────────────────────────────────────
 53	
 54	function requireEnv(name: string): string {
 55	  const val = process.env[name];
 56	  if (!val) throw new Error(`Required env var ${name} is not set`);
 57	  return val;
 58	}
 59	
 60	function emit(event: Record<string, unknown>): void {
 61	  console.log(JSON.stringify({ at: new Date().toISOString(), ...event }));
 62	}
 63	
 64	function writeResult(resultPath: string, result: ExecutorResult): void {
 65	  mkdirSync(dirname(resultPath), { recursive: true });
 66	  writeFileSync(resultPath, JSON.stringify(result), "utf-8");
 67	}
 68	
 69	const TOOLCHAIN_MARKERS: Array<{ file: string; tool: string }> = [
 70	  { file: "yarn.lock",        tool: "yarn"    },
 71	  { file: "pnpm-lock.yaml",   tool: "pnpm"    },
 72	  { file: "bun.lockb",        tool: "bun"     },
 73	  { file: "go.mod",           tool: "go"      },
 74	  { file: "requirements.txt", tool: "python3" },
 75	  { file: "pyproject.toml",   tool: "python3" },
 76	  { file: "Cargo.toml",       tool: "cargo"   },
 77	];
 78	
 79	export function checkRequiredTools(taskRepoPath: string): string[] {
 80	  const missing: string[] = [];
 81	  const checked = new Set<string>();
 82	  for (const { file, tool } of TOOLCHAIN_MARKERS) {
 83	    if (checked.has(tool)) continue;
 84	    if (!existsSync(join(taskRepoPath, file))) continue;
 85	    checked.add(tool);
 86	    try {
 87	      execSync(`which ${tool}`, { stdio: "pipe" });
 88	    } catch {
 89	      missing.push(tool);
 90	    }
 91	  }
 92	  return missing;
 93	}
 94	
 95	// ── Phase 3.5 helpers ─────────────────────────────────────────────────────────
 96	
 97	/** Recursively copy a directory tree from src to dest. */
 98	export function copyDirRecursive(src: string, dest: string): void {
 99	  mkdirSync(dest, { recursive: true });
100	  for (const entry of readdirSync(src, { withFileTypes: true })) {
101	    const srcPath = join(src, entry.name);
102	    const destPath = join(dest, entry.name);
103	    if (entry.isDirectory()) {
104	      copyDirRecursive(srcPath, destPath);
105	    } else {
106	      copyFileSync(srcPath, destPath);
107	    }
108	  }
109	}
110	
111	// ── Phase 3.5: exported for testing ───────────────────────────────────────────
112	
113	export interface Phase35Result {
114	  soulCopied: boolean;
115	  skillsCopied: string[];
116	  hermesMdCopied: boolean;
117	  excludeUpdated: boolean;
118	  skipped: boolean;
119	}
120	
121	/**
122	 * Run Phase 3.5 — Hermes context + skill staging.
123	 * Independently guarded: each sub-step only runs if its source exists.
124	 * Safe to call when WORKFLOW_LOCAL_PATH is unset (returns skipped=true).
125	 */
126	export function runPhase35(opts: {
127	  workflowLocalPath: string;
128	  hermesHome: string;
129	  mgmtDir: string;
130	  implDir: string;
131	  emitFn?: (event: Record<string, unknown>) => void;
132	}): Phase35Result {
133	  const { workflowLocalPath, hermesHome, mgmtDir, implDir, emitFn } = opts;
134	  const result: Phase35Result = { soulCopied: false, skillsCopied: [], hermesMdCopied: false, excludeUpdated: false, skipped: false };
135	
136	  if (!workflowLocalPath) {
137	    result.skipped = true;
138	    emitFn?.({ type: "phase_3_5_skipped", reason: "WORKFLOW_LOCAL_PATH not set" });
139	    return result;
140	  }
141	
142	  const hermesSrc = join(workflowLocalPath, "hermes");
143	
144	  // 3.5a — Tier 1 → Tier 3: SOUL.md → ~/.hermes/SOUL.md
145	  const soulSrc = join(hermesSrc, "SOUL.md");
146	  if (existsSync(soulSrc)) {
147	    copyFileSync(soulSrc, join(hermesHome, "SOUL.md"));
148	    result.soulCopied = true;
149	  }
150	
151	  // 3.5b — Tier 1 → Tier 3: workflow_skills/ + technical_skills/ → ~/.hermes/skills/
152	  const targetSkillsDir = join(hermesHome, "skills");
153	  if (existsSync(targetSkillsDir)) rmSync(targetSkillsDir, { recursive: true, force: true });
154	  mkdirSync(targetSkillsDir, { recursive: true });
155	  for (const srcName of ["workflow_skills", "technical_skills"]) {
156	    const src = join(hermesSrc, srcName);
157	    if (existsSync(src)) {
158	      for (const entry of readdirSync(src)) {
159	        copyDirRecursive(join(src, entry), join(targetSkillsDir, entry));
160	        result.skillsCopied.push(entry);
161	      }
162	    }
163	  }
164	
165	  // 3.5c — Tier 2 → Tier 3: <mgmtDir>/HERMES.md → <implDir>/HERMES.md
166	  const workspaceHermesMd = join(mgmtDir, "HERMES.md");
167	  if (existsSync(workspaceHermesMd)) {
168	    copyFileSync(workspaceHermesMd, join(implDir, "HERMES.md"));
169	    result.hermesMdCopied = true;
170	
171	    // 3.5d — Append to .git/info/exclude so Phase 6 git add -A does not stage HERMES.md
172	    const excludePath = join(implDir, ".git", "info", "exclude");
173	    if (existsSync(dirname(excludePath))) {
174	      const existing = existsSync(excludePath) ? readFileSync(excludePath, "utf-8") : "";
175	      if (!existing.includes("HERMES.md")) {
176	        appendFileSync(excludePath, "\n# Hermes auto-loaded workspace rules (local-only)\nHERMES.md\n");
177	      }
178	      result.excludeUpdated = true;
179	    }
180	  } else {
181	    emitFn?.({ type: "phase_3_5_workspace_hermes_missing", workspace_hermes_md: workspaceHermesMd });
182	  }
183	
184	  return result;
185	}
