187	// ── Phase 6 helpers ────────────────────────────────────────────────────────────
188	
189	/**
190	 * Stage all changes in repoDir, commit with a conventional message, and push.
191	 * Returns true if a commit was made, false when the working tree was already clean.
192	 */
193	export function commitAndPush(opts: {
194	  repoDir: string;
195	  taskId: string;
196	  featureId: string;
197	  sshKeyPath: string | undefined;
198	  gitAuthorEmail: string;
199	  gitAuthorName: string;
200	  /** When provided, also checks for pre-committed unpushed work ahead of origin/<branch>. */
201	  branch?: string;
202	}): boolean {
203	  const { repoDir, taskId, featureId, sshKeyPath, gitAuthorEmail, gitAuthorName, branch } = opts;
204	  const gitEnv = buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName });
205	  const execOpts = { env: gitEnv, stdio: "pipe" as const };
206	
207	  execSync(`git -C "${repoDir}" add -A`, execOpts);
208	
209	  const porcelain = execSync(`git -C "${repoDir}" status --porcelain`, {
210	    ...execOpts, encoding: "utf-8",
211	  }).trim();
212	  if (porcelain) {
213	    execSync(
214	      `git -C "${repoDir}" commit -m "feat(${featureId}/${taskId}): hermes agent code changes"`,
215	      execOpts,
216	    );
217	  }
218	
219	  // Also return true if Hermes pre-committed work that hasn't been pushed yet.
220	  // This handles the case where Hermes committed incrementally (clean working tree)
221	  // but the wrapper-push path never ran.
222	  if (branch) {
223	    try {
224	      execSync(`git -C "${repoDir}" rev-parse --verify "origin/${branch}"`, execOpts);
225	      const unpushed = execSync(
226	        `git -C "${repoDir}" log "origin/${branch}..HEAD" --oneline`,
227	        { ...execOpts, encoding: "utf-8" },
228	      ).trim();
229	      if (unpushed) return true;
230	    } catch { /* origin/<branch> doesn't exist or error — fall through */ }
231	  }
232	
233	  return !!porcelain;
234	}
235	
236	export function pushBranch(opts: {
237	  repoDir: string;
238	  branch: string;
239	  sshKeyPath: string | undefined;
240	  gitAuthorEmail: string;
241	  gitAuthorName: string;
242	}): void {
243	  const { repoDir, branch, sshKeyPath, gitAuthorEmail, gitAuthorName } = opts;
244	  execSync(
245	    `git -C "${repoDir}" push origin "${branch}"`,
246	    {
247	      env: buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName }),
248	      stdio: "pipe" as const,
249	    },
250	  );
251	}
