253	/**
254	 * Open an impl PR via the GitHub REST API (curl).
255	 * If a PR already exists for the head branch, returns the existing PR URL.
256	 * Returns the PR html_url on success, throws on failure.
257	 */
258	export function openImplPR(opts: {
259	  taskRepoUrl: string;
260	  featureId: string;
261	  taskId: string;
262	  head: string;
263	  base: string;
264	  githubToken: string;
265	}): string {
266	  const { taskRepoUrl, featureId, taskId, head, base, githubToken } = opts;
267	  const { owner, repo } = parseGitHubCoords(taskRepoUrl);
268	
269	  // Check for an existing open PR on this branch first.
270	  const encodedHead = encodeURIComponent(`${owner}:${head}`);
271	  const listResult = spawnSync("curl", [
272	    "-s",
273	    "-H", `Authorization: token ${githubToken}`,
274	    "-H", "Accept: application/vnd.github+json",
275	    `https://api.github.com/repos/${owner}/${repo}/pulls?head=${encodedHead}&state=open`,
276	  ], { encoding: "utf-8", stdio: ["ignore", "pipe", "pipe"] });
277	
278	  if (!listResult.error) {
279	    const existing = JSON.parse(listResult.stdout ?? "[]") as Array<{ html_url: string }>;
280	    if (Array.isArray(existing) && existing.length > 0) {
281	      return existing[0].html_url;
282	    }
283	  }
284	
285	  const title = `feat(${featureId}/${taskId}): hermes agent implementation`;
286	  const body = [
287	    `## Task: ${taskId}`,
288	    "",
289	    `**Feature:** ${featureId}`,
290	    `**Branch:** \`${head}\``,
291	    "",
292	    "Implemented by Hermes executor — wrapper opened this PR after agent completed code changes.",
293	  ].join("\n");
294	
295	  const createResult = spawnSync("curl", [
296	    "-s", "-X", "POST",
297	    "-H", `Authorization: token ${githubToken}`,
298	    "-H", "Accept: application/vnd.github+json",
299	    "-H", "Content-Type: application/json",
300	    "-d", JSON.stringify({ title, body, head, base, draft: true }),
301	    `https://api.github.com/repos/${owner}/${repo}/pulls`,
302	  ], { encoding: "utf-8", stdio: ["ignore", "pipe", "pipe"] });
303	
304	  if (createResult.error) throw createResult.error;
305	
306	  const created = JSON.parse(createResult.stdout ?? "{}") as { html_url?: string };
307	  if (!created.html_url) {
308	    throw new Error(`GitHub PR creation failed: ${createResult.stdout}`);
309	  }
310	  return created.html_url;
311	}
