313	// ── Phase 1 + 2: repo materialisation ─────────────────────────────────────────
314	
315	/**
316	 * Clone or pull a repo at targetDir on the given branch.
317	 * If targetDir already contains a valid clone of the same URL,
318	 * fetch + checkout + pull instead of re-cloning.
319	 */
320	export function cloneOrPull(
321	  url: string,
322	  targetDir: string,
323	  branch: string,
324	  sshKeyPath: string | undefined,
325	): void {
326	  const env = buildGitEnv(sshKeyPath);
327	  const opts = { env, stdio: "pipe" as const };
328	
329	  if (existsSync(join(targetDir, ".git"))) {
330	    let originUrl = "";
331	    try {
332	      originUrl = execSync(`git -C "${targetDir}" remote get-url origin`, {
333	        ...opts, encoding: "utf-8",
334	      }).trim();
335	    } catch { /* no remote — fall through to clone */ }
336	
337	    if (originUrl === url) {
338	      execSync(`git -C "${targetDir}" fetch origin`, opts);
339	      try {
340	        execSync(`git -C "${targetDir}" checkout -- .`, opts);
341	      } catch { /* ignore */ }
342	      try {
343	        execSync(`git -C "${targetDir}" checkout "${branch}"`, opts);
344	      } catch {
345	        execSync(`git -C "${targetDir}" checkout -b "${branch}"`, opts);
346	      }
347	      try {
348	        execSync(`git -C "${targetDir}" pull --ff-only origin "${branch}"`, opts);
349	      } catch {
350	        emit({ type: "repo_pull_diverged", dir: targetDir, branch, note: "ff-only failed — using checked-out ref" });
351	      }
352	      return;
353	    }
354	  }
355	
356	  mkdirSync(dirname(targetDir), { recursive: true });
357	  if (existsSync(targetDir)) {
358	    rmSync(targetDir, { recursive: true, force: true });
359	  }
360	  execSync(`git clone "${url}" "${targetDir}"`, opts);
361	  try {
362	    execSync(`git -C "${targetDir}" checkout "${branch}"`, opts);
363	  } catch {
364	    execSync(`git -C "${targetDir}" checkout -b "${branch}"`, opts);
365	  }
366	}
