368	/**
369	 * Materialize the management repo on the task branch.
370	 * Falls back to main if the task branch is not yet on origin.
371	 */
372	export function materializeMgmtRepo(
373	  mgmtRepoUrl: string,
374	  mgmtDir: string,
375	  sshKeyPath: string | undefined,
376	  taskBranch: string,
377	): void {
378	  const env = buildGitEnv(sshKeyPath);
379	  const opts = { env, stdio: "pipe" as const };
380	
381	  const checkoutTaskBranch = (dir: string): void => {
382	    try {
383	      execSync(`git -C "${dir}" checkout -B "${taskBranch}" "origin/${taskBranch}"`, opts);
384	    } catch (taskBranchErr) {
385	      try {
386	        execSync(`git -C "${dir}" checkout main`, opts);
387	      } catch (e) {
388	        emit({ type: "mgmt_repo_checkout_failed", dir, branch: "main", details: String(e) });
389	      }
390	      try {
391	        execSync(`git -C "${dir}" pull --ff-only origin main`, opts);
392	      } catch {
393	        emit({ type: "mgmt_repo_pull_diverged", dir, note: "ff-only failed", task_branch_err: String(taskBranchErr) });
394	      }
395	    }
396	  };
397	
398	  if (existsSync(join(mgmtDir, ".git"))) {
399	    let originUrl = "";
400	    try {
401	      originUrl = execSync(`git -C "${mgmtDir}" remote get-url origin`, {
402	        ...opts, encoding: "utf-8",
403	      }).trim();
404	    } catch { /* no remote */ }
405	
406	    if (originUrl === mgmtRepoUrl) {
407	      execSync(`git -C "${mgmtDir}" fetch origin`, opts);
408	      checkoutTaskBranch(mgmtDir);
409	      return;
410	    }
411	  }
412	
413	  mkdirSync(dirname(mgmtDir), { recursive: true });
414	  if (existsSync(mgmtDir)) {
415	    rmSync(mgmtDir, { recursive: true, force: true });
416	  }
417	  execSync(`git clone "${mgmtRepoUrl}" "${mgmtDir}"`, opts);
418	  checkoutTaskBranch(mgmtDir);
419	}
