421	// ── Phase 3: Hermes config ─────────────────────────────────────────────────────
422	
423	export interface HermesConfig {
424	  provider: string;
425	  model: string;
426	  ragMcpUrl?: string;
427	  ragMcpToken?: string;
428	  gitnexusMcpUrl?: string;
429	}
