431	/**
432	 * Write HERMES_HOME/config.yaml with model stanza and optional RAG MCP stanza.
433	 * No memory stanza — stateless by default (Mem0 is hermes-workspace-memory scope).
434	 */
435	export function writeHermesConfig(hermesHome: string, config: HermesConfig): void {
436	  mkdirSync(hermesHome, { recursive: true });
437	
438	  const configObj: Record<string, unknown> = {
439	    model: {
440	      provider: config.provider,
441	      default: config.model,
442	    },
443	  };
444	
445	  if (config.ragMcpUrl || config.gitnexusMcpUrl) {
446	    configObj.mcp_servers = {} as Record<string, unknown>;
447	    if (config.ragMcpUrl) {
448	      (configObj.mcp_servers as Record<string, unknown>).rag = {
449	        url: config.ragMcpUrl,
450	        ...(config.ragMcpToken
451	          ? { headers: { Authorization: `Bearer ${config.ragMcpToken}` } }
452	          : {}),
453	      };
454	    }
455	    if (config.gitnexusMcpUrl) {
456	      (configObj.mcp_servers as Record<string, unknown>).gitnexus = {
457	        url: config.gitnexusMcpUrl,
458	      };
459	    }
460	  }
461	
462	  writeFileSync(join(hermesHome, "config.yaml"), yamlStringify(configObj), "utf-8");
463	}
