465	// ── Phase 5: Hermes spawn ──────────────────────────────────────────────────────
466	
467	interface HermesSpawnOpts {
468	  briefing: string;
469	  hermesHome: string;
470	  hermesModel: string;
471	  hermesProvider: string;
472	  hermesMaxTurns: string;
473	  taskRepoPath: string;
474	}
475	
476	function spawnHermes(opts: HermesSpawnOpts): Promise<SpawnResult> {
477	  const {
478	    briefing,
479	    hermesHome,
480	    hermesModel,
481	    hermesProvider,
482	    hermesMaxTurns,
483	    taskRepoPath,
484	  } = opts;
485	
486	  return new Promise((resolve) => {
487	    const env: NodeJS.ProcessEnv = {
488	      ...process.env,
489	      HERMES_HOME: hermesHome,
490	      HERMES_INFERENCE_MODEL: hermesModel,
491	      HERMES_INFERENCE_PROVIDER: hermesProvider,
492	      HERMES_MAX_ITERATIONS: hermesMaxTurns,
493	      HERMES_YOLO_MODE: "1",
494	      AGENT_RUNTIME: "1",
495	    };
496	
497	    const child = spawn(
498	      "hermes",
499	      ["chat", "--query", briefing],
500	      {
501	        cwd: taskRepoPath,
502	        env,
503	        stdio: ["ignore", "pipe", "pipe"],
504	      },
505	    );
506	
507	    let stdout = "";
508	    child.stdout.on("data", (chunk: Buffer) => {
509	      const s = chunk.toString();
510	      stdout += s;
511	      process.stdout.write(s);
512	    });
513	    child.stderr.on("data", (chunk: Buffer) => {
514	      process.stderr.write(chunk);
515	    });
516	
517	    child.on("error", (error: Error) => {
518	      resolve({ stdout, status: null, signal: null, error });
519	    });
520	
521	    child.on("close", (code: number | null, signal: NodeJS.Signals | null) => {
522	      resolve({ stdout, status: code, signal });
523	    });
524	  });
525	}
