527	// ── Main ──────────────────────────────────────────────────────────────────────
528	
529	async function main(): Promise<void> {
530	  let taskId: string;
531	  let featureId: string;
532	  let workspaceId: string;
533	  let taskRepoUrl: string;
534	  let taskRepoBranch: string;
535	  let taskBaseBranch: string;
536	  let executorWorkdir: string;
537	  let mgmtRepoUrl: string;
538	  let resultPath: string;
539	  let githubToken: string;
540	  let sshKeyPath: string | undefined;
541	
542	  try {
543	    taskId = requireEnv("TASK_ID");
544	    featureId = requireEnv("FEATURE_ID");
545	    workspaceId = requireEnv("WORKSPACE_ID");
546	    taskRepoUrl = requireEnv("TASK_REPO_URL");
547	    taskRepoBranch = requireEnv("TASK_REPO_BRANCH");
548	    taskBaseBranch = process.env.TASK_BASE_BRANCH ?? "main";
549	    executorWorkdir = requireEnv("EXECUTOR_WORKDIR");
550	    mgmtRepoUrl = requireEnv("MGMT_REPO_URL");
551	    resultPath = requireEnv("RESULT_PATH");
552	    githubToken = process.env.GITHUB_TOKEN ?? "";
553	    mkdirSync(executorWorkdir, { recursive: true });
554	    sshKeyPath = resolveSSHKey({ SSH_PRIVATE_KEY: process.env.SSH_PRIVATE_KEY }, executorWorkdir).sshKeyPath;
555	  } catch (e) {
556	    emit({ type: "executor_fatal", details: (e as Error).message });
557	    process.exit(1);
558	  }
559	
560	  const taskRepoBaseBranch = process.env.TASK_REPO_BASE_BRANCH ?? "";
561	  const taskBranch = process.env.TASK_BRANCH ?? `feature/${featureId}-${taskId}`;
562	  const gitAuthorEmail = process.env.GIT_AUTHOR_EMAIL ?? "agent@unknown";
563	  const gitAuthorName = process.env.GIT_AUTHOR_NAME ?? gitAuthorEmail;
564	
565	  const hermesModel = process.env.HERMES_INFERENCE_MODEL ?? "default";
566	  const hermesProvider = process.env.HERMES_INFERENCE_PROVIDER ?? "openai";
567	  const hermesMaxTurns = process.env.HERMES_MAX_TURNS ?? "150";
568	  const ragMcpUrl = process.env.RAG_MCP_URL;
569	  const ragMcpToken = process.env.RAG_MCP_TOKEN;
570	  const gitnexusMcpUrl = process.env.GITNEXUS_MCP_URL;
571	  const logSinkEnabled = process.env.LOG_SINK_ENABLED === "1";
572	  const runStartIso = new Date().toISOString();
573	
574	  const implDir = join(executorWorkdir, "impl");
575	  const mgmtDir = join(executorWorkdir, "mgmt");
576	  const hermesHome = join(executorWorkdir, "hermes-home");
577	
578	  // Phases 1–4 use terminal_status "failed" (not "blocked") because they are pre-execution
579	  // infrastructure failures — the executor never reached the work phase. The orchestrator
580	  // maps "failed" → blocked/executor_failed. "blocked" is reserved for task-level outcomes
581	  // (no_changes, test failures, etc.) where the executor ran but work could not be completed.
582	
583	  // ── Phase 1: Management repo ───────────────────────────────────────────────
584	  emit({ type: "phase_start", phase: 1, description: "clone management repo" });
585	  try {
586	    materializeMgmtRepo(mgmtRepoUrl, mgmtDir, sshKeyPath, taskBranch);
587	    process.env.WORKSPACE_ROOT = mgmtDir;
588	    emit({ type: "phase_done", phase: 1, mgmt_dir: mgmtDir });
589	  } catch (e) {
590	    emit({ type: "executor_fatal", task_id: taskId, details: `mgmt repo materialization failed: ${String(e)}` });
591	    writeResult(resultPath, {
592	      terminal_status: "failed",
593	      blocked_reason: `mgmt_repo_materialization_failed: ${String(e)}`,
594	    });
595	    process.exit(0);
596	  }
597	
598	  // ── Phase 2: Implementation repo ──────────────────────────────────────────
599	  emit({ type: "phase_start", phase: 2, description: "clone implementation repo" });
600	  try {
601	    cloneOrPull(taskRepoUrl, implDir, taskRepoBranch, sshKeyPath);
602	    process.env.TASK_REPO_PATH = implDir;
603	    emit({ type: "phase_done", phase: 2, impl_dir: implDir });
604	  } catch (e) {
605	    emit({ type: "executor_fatal", task_id: taskId, details: `impl repo materialization failed: ${String(e)}` });
606	    writeResult(resultPath, {
607	      terminal_status: "failed",
608	      blocked_reason: `impl_repo_materialization_failed: ${String(e)}`,
609	    });
610	    process.exit(0);
611	  }
612	
613	  // Ensure `feature/{featureId}` exists on the impl repo remote so the PR can
614	  // target it. Uses TASK_REPO_BASE_BRANCH (the repo's root base, e.g. "main")
615	  // as the SHA source — not TASK_BASE_BRANCH, which is the feature branch itself.
616	  if (taskRepoBaseBranch) {
617	    const ok = ensureImplFeatureBranch(featureId, taskRepoBaseBranch, implDir, sshKeyPath, emit);
618	    if (!ok) {
619	      emit({ type: "executor_fatal", task_id: taskId, details: "impl feature branch creation failed" });
620	      writeResult(resultPath, {
621	        terminal_status: "blocked",
622	        blocked_reason: "impl_feature_branch_failed",
623	        blocked_suggestion: `Ensure the SSH key has push access to the impl repo and that origin/${taskRepoBaseBranch} exists, then retry.`,
624	      });
625	      process.exit(0);
626	    }
627	  }
628	
629	  // Toolchain pre-flight: fail early with a clear message rather than letting
630	  // Hermes hit a 127 "command not found" mid-task and produce an opaque failure.
631	  const missingTools = checkRequiredTools(implDir);
632	  if (missingTools.length > 0) {
633	    emit({ type: "preflight_failed", task_id: taskId, feature_id: featureId, details: `missing tools: ${missingTools.join(", ")}` });
634	    writeResult(resultPath, {
635	      terminal_status: "blocked",
636	      blocked_reason: "missing_tool",
637	      blocked_suggestion: `Install missing tools in the executor image: ${missingTools.join(", ")}`,
638	    });
639	    process.exit(0);
640	  }
641	
642	  // ── Phase 3: Hermes home + config.yaml ────────────────────────────────────
643	  emit({ type: "phase_start", phase: 3, description: "write HERMES_HOME/config.yaml" });
644	  try {
645	    writeHermesConfig(hermesHome, {
646	      provider: hermesProvider,
647	      model: hermesModel,
648	      ragMcpUrl,
649	      ragMcpToken,
650	      gitnexusMcpUrl,
651	    });
652	    process.env.HERMES_HOME = hermesHome;
653	    emit({ type: "phase_done", phase: 3, hermes_home: hermesHome });
654	  } catch (e) {
655	    emit({ type: "executor_fatal", task_id: taskId, details: `hermes config write failed: ${String(e)}` });
656	    writeResult(resultPath, {
657	      terminal_status: "failed",
658	      blocked_reason: `hermes_config_write_failed: ${String(e)}`,
659	    });
660	    process.exit(0);
661	  }
662	
663	  // ── Phase 3.5: Hermes context + skill staging ─────────────────────────────
664	  emit({ type: "phase_start", phase: 3.5, description: "Hermes context + skill staging" });
665	  try {
666	    const phase35 = runPhase35({
667	      workflowLocalPath: process.env.WORKFLOW_LOCAL_PATH ?? "",
668	      hermesHome,
669	      mgmtDir,
670	      implDir,
671	      emitFn: emit,
672	    });
673	    emit({ type: "phase_done", phase: 3.5, ...phase35 });
674	  } catch (e) {
675	    // Phase 3.5 failures are non-fatal — Hermes can still run with degraded context.
676	    emit({ type: "phase_3_5_error", details: String(e) });
677	  }
678	
679	  // ── Phase 4: Build briefing ─────────────────────────────────

content.content:
1	/**
2	 * Hermes executor entrypoint — ABI-conformant.
3	 *
4	 * Reads ExecutorInput from environment variables, runs phases 1–5, then
5	 * post-execution (Phase 6) commits, pushes, opens the impl PR, and writes result.json.
6	 *
7	 * Formal ABI env vars (from ExecutorInput):
8	 *   TASK_ID, FEATURE_ID, WORKSPACE_ID, HANDLE
