if (!isValidResult(raw)) return false;

let claudeResult = raw as ExecutorResult;
if (tokenUsage !== undefined && !claudeResult.token_usage) {
  claudeResult.token_usage = { input: tokenUsage.input, output: tokenUsage.output, model: tokenUsage.model };
}
if (tokenUsage !== undefined && claudeResult.cost_usd === undefined) {
  claudeResult.cost_usd = tokenUsage.cost_usd;
}

// Build executor_audit from token usage and MCP query data.
if (!claudeResult.executor_audit) {
  const claudeAudit: ClaudeExecutorAudit = {
    ...(tokenUsage !== undefined && { token_usage: { input: tokenUsage.input, output: tokenUsage.output, model: tokenUsage.model } }),
    ...((ragQueryAudit.length > 0 || gitnexusQueryAudit.length > 0) && {
      mcp_usage: { rag_queries: ragQueryAudit, gitnexus_queries: gitnexusQueryAudit },
    }),
  };
  const executorAudit: ExecutorAudit = {
    ...(tokenUsage !== undefined && { cost_usd: tokenUsage.cost_usd }),
    ...(Object.keys(claudeAudit).length > 0 && { claude: claudeAudit }),
  };
  if (Object.keys(executorAudit).length > 0) {
    claudeResult.executor_audit = executorAudit;
  }
}

// Refuse terminal_status: in_review without a valid pr_url. Checks:
//   1. pr_url must be present and non-empty.
//   2. pr_url owner/repo must match the task's implementation repo.
//   3. PR head branch must be feature/{featureId}-{taskId} (API-verified).
let prUrlCtx: Parameters<typeof enforceInReviewRequiresPrUrl>[1];
try {
  const { owner, repo } = parseGitHubCoords(taskRepoUrl);
  prUrlCtx = { expectedOwner: owner, expectedRepo: repo, featureId, taskId, githubToken: githubToken || undefined };
} catch {
  prUrlCtx = undefined;
}
const enforced = enforceInReviewRequiresPrUrl(claudeResult, prUrlCtx);
if (enforced.rewritten) {
  emit({
    type: "in_review_refused_no_pr_url",
    task_id: taskId,
    feature_id: featureId,
    blocked_reason: enforced.result.blocked_reason,
  });

