describe("buildHermesAudit", () => {
  it("returns empty object for empty stdout", () => {
    expect(buildHermesAudit("")).toEqual({});
  });

  it("returns empty object when stdout has no structured JSON lines", () => {
    const stdout = "Starting Hermes...\nDone.\nSome plain text output";
    expect(buildHermesAudit(stdout)).toEqual({});
  });

  it("counts turn events from structured JSON stdout", () => {
    const lines = [
      JSON.stringify({ type: "turn", index: 1 }),
      JSON.stringify({ type: "turn", index: 2 }),
      JSON.stringify({ type: "turn", index: 3 }),
    ].join("\n");
    expect(buildHermesAudit(lines)).toEqual({ turns: 3 });
  });

  it("counts tool_call events from structured JSON stdout", () => {
    const lines = [
      JSON.stringify({ type: "tool_call", tool: "read_file" }),
      JSON.stringify({ type: "tool_call", tool: "write_file" }),
    ].join("\n");
    expect(buildHermesAudit(lines)).toEqual({ turns: 2 });
  });

  it("counts mixed event types from structured JSON stdout", () => {
    const lines = [
      JSON.stringify({ type: "turn", index: 1 }),
      "plain text line",
      JSON.stringify({ type: "assistant_message", content: "hello" }),
      JSON.stringify({ type: "tool_call", tool: "bash" }),
      JSON.stringify({ type: "other_event", data: "ignored" }),
    ].join("\n");
    expect(buildHermesAudit(lines)).toEqual({ turns: 3 });
  });

  it("ignores non-turn JSON events", () => {
    const lines = [
      JSON.stringify({ type: "phase_start", phase: 1 }),
      JSON.stringify({ type: "phase_done", phase: 1 }),
      JSON.stringify({ type: "executor_fatal", details: "error" }),
    ].join("\n");
    expect(buildHermesAudit(lines)).toEqual({});
  });

  it("returns empty object when stdout has only invalid JSON lines", () => {
    const stdout = "{ not valid json }\n{ also bad\nnot json at all";
    expect(buildHermesAudit(stdout)).toEqual({});
  });

  it("counts iteration events", () => {
    const lines = [
      JSON.stringify({ type: "iteration", step: 1 }),
      JSON.stringify({ type: "iteration", step: 2 }),
    ].join("\n");
    expect(buildHermesAudit(lines)).toEqual({ turns: 2 });
  });
});

